DROP TABLE IF EXISTS `static_analysis_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `static_analysis_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `app_version_id` bigint(20) unsigned NOT NULL,
  `session_stamp` varchar(128) DEFAULT NULL,
  `scope_label` varchar(191) DEFAULT NULL,
  `sha256` char(64) DEFAULT NULL,
  `analysis_version` varchar(32) DEFAULT NULL,
  `profile` varchar(32) DEFAULT NULL,
  `findings_total` int(10) unsigned NOT NULL DEFAULT 0,
  `detector_metrics` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`detector_metrics`)),
  `repro_bundle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`repro_bundle`)),
  `analysis_matrices` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`analysis_matrices`)),
  `analysis_indicators` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`analysis_indicators`)),
  `workload_profile` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`workload_profile`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `pipeline_version` varchar(32) DEFAULT NULL,
  `catalog_versions` varchar(128) DEFAULT NULL,
  `config_hash` char(64) DEFAULT NULL,
  `study_tag` varchar(128) DEFAULT NULL,
  `run_started_utc` varchar(64) DEFAULT NULL,
  `status` varchar(16) DEFAULT 'RUNNING',
  `ended_at_utc` datetime DEFAULT NULL,
  `abort_reason` varchar(64) DEFAULT NULL,
  `abort_signal` varchar(16) DEFAULT NULL,
  `category` varchar(64) DEFAULT NULL,
  `base_apk_sha256` char(64) DEFAULT NULL,
  `artifact_set_hash` char(64) DEFAULT NULL,
  `run_signature` char(64) DEFAULT NULL,
  `run_signature_version` varchar(16) DEFAULT NULL,
  `identity_valid` tinyint(1) DEFAULT NULL,
  `identity_error_reason` varchar(128) DEFAULT NULL,
  `profile_key` varchar(64) DEFAULT NULL,
  `scenario_id` varchar(64) DEFAULT NULL,
  `device_serial` varchar(128) DEFAULT NULL,
  `tool_semver` varchar(32) DEFAULT NULL,
  `tool_git_commit` varchar(40) DEFAULT NULL,
  `schema_version` varchar(32) DEFAULT NULL,
  `session_label` varchar(128) DEFAULT NULL,
  `is_canonical` tinyint(1) DEFAULT NULL,
  `canonical_set_at_utc` datetime DEFAULT NULL,
  `canonical_reason` varchar(64) DEFAULT NULL,
  `identity_mode` varchar(32) DEFAULT NULL,
  `identity_conflict_flag` tinyint(1) DEFAULT 0,
  `static_handoff_hash` char(64) DEFAULT NULL,
  `static_handoff_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`static_handoff_json`)),
  `static_handoff_json_path` text DEFAULT NULL,
  `masvs_mapping_hash` char(64) DEFAULT NULL,
  `run_class` varchar(32) DEFAULT NULL,
  `non_canonical_reasons` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`non_canonical_reasons`)),
  `findings_runtime_total` int(10) unsigned DEFAULT NULL,
  `findings_capped_total` int(10) unsigned DEFAULT NULL,
  `findings_capped_by_detector_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`findings_capped_by_detector_json`)),
  PRIMARY KEY (`id`),
  KEY `ix_static_runs_version` (`app_version_id`),
  KEY `ix_static_runs_session` (`session_stamp`),
  KEY `ix_static_runs_sha` (`sha256`),
  KEY `ix_static_runs_session_version` (`session_stamp`,`app_version_id`),
  KEY `ix_static_runs_category` (`category`),
  KEY `ix_static_runs_session_label` (`session_label`),
  KEY `ix_static_runs_canonical` (`session_label`,`is_canonical`)
) ENGINE=InnoDB AUTO_INCREMENT=2726 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
