/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_static_runs_canonical_update` BEFORE UPDATE ON `static_analysis_runs`
 FOR EACH ROW BEGIN
                  IF NEW.is_canonical = 1 THEN
                    IF EXISTS (
                      SELECT 1
                      FROM static_analysis_runs
                      WHERE session_label = NEW.session_label
                        AND is_canonical = 1
                        AND id <> NEW.id
                    ) THEN
                      SIGNAL SQLSTATE '45000'
                        SET MESSAGE_TEXT = 'canonical constraint violated (session_label already has canonical)';
                    END IF;
                  END IF;
                END */;;
DELIMITER ;
